using Godot;
using System;
using System.IO;
using System.Linq;
public partial class MigrationScene {
 void BuildUi(){NewHud();}
 void UpdateHud(){ComicHud();}
 VBoxContainer Panel(string title){bool entering=!paused;coopMenu="";if(menu!=null){ui.RemoveChild(menu);menu.QueueFree();}paused=true;if(ambience!=null)ambience.StreamPaused=true;Input.MouseMode=Input.MouseModeEnum.Visible;menu=new PanelContainer{Position=new Vector2(160,30),Size=new Vector2(960,650),Theme=comicTheme};if(menuShade==null){menuShade=new ColorRect{Color=new Color(.015f,.025f,.025f,.42f)};menuShade.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);ui.AddChild(menuShade);}menuShade.Visible=true;ui.AddChild(menu);if(entering){menu.Modulate=new Color(1,1,1,.75f);menu.CreateTween().TweenProperty(menu,"modulate:a",1f,.12);}hudRoot.Visible=false;var margin=new MarginContainer();foreach(string key in new[]{"margin_left","margin_top","margin_right","margin_bottom"})margin.AddThemeConstantOverride(key,18);menu.AddChild(margin);var scroll=new ScrollContainer{HorizontalScrollMode=ScrollContainer.ScrollMode.Auto,VerticalScrollMode=ScrollContainer.ScrollMode.Auto};margin.AddChild(scroll);var box=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};box.AddThemeConstantOverride("separation",9);scroll.AddChild(box);var heading=new Label{Text=title};heading.AddThemeFontSizeOverride("font_size",23);heading.AddThemeColorOverride("font_color",new Color(.88f,.75f,.48f));box.AddChild(heading);box.AddChild(new HSeparator());return box;}
 void Text(VBoxContainer box,string text){box.AddChild(new Label{Text=text,AutowrapMode=TextServer.AutowrapMode.WordSmart,CustomMinimumSize=new Vector2(880,0)});}
 void Button(Container box,string title,Action action){var button=new Godot.Button{Text=title,TooltipText=title,ClipText=box is GridContainer,CustomMinimumSize=box is GridContainer?new Vector2(430,38):new Vector2(0,38),MouseDefaultCursorShape=Control.CursorShape.PointingHand};box.AddChild(button);button.Pressed+=action;}
 void CloseMenu(){if(menuShade!=null)menuShade.Visible=false;coopMenu="";if(menu!=null){ui.RemoveChild(menu);menu.QueueFree();menu=null;}paused=false;if(ambience!=null)ambience.StreamPaused=muted;Input.MouseMode=testing?Input.MouseModeEnum.Visible:Input.MouseModeEnum.Captured;}
 void ShowCrafting(){ComicCrafting();}
 void ShowEquipment(){ComicEquipment();}
 void ShowSkills(){ShowProgression();}
 void ShowCamps(){var b=Panel("SLEEPING BAGS / RESPAWN / TRAVEL");coopMenu="camps";Text(b,"Bag kits "+game.Life.Bags+" / travel needs daylight, no wounds, safe camps, 1 food + 1 water + 25 energy. Ten-minute cooldown.");Button(b,"SURVIVOR COMMUNITY / F7",()=>ShowCommunity());Button(b,"PLACE BAG HERE",()=>{if(!CoopRequest("bag"))game.AddBag(player.Position.X,player.Position.Z,CampSafe);SyncCampObjects();ShowCamps();});var sc=new ScrollContainer{CustomMinimumSize=new Vector2(880,270)};b.AddChild(sc);var rows=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};sc.AddChild(rows);foreach(var camp in game.Life.Camps.Where(c=>c.Seed==game.Save.Seed)){var copy=camp;Text(rows,(camp.Id==game.Life.Respawn?"[RESPAWN] ":"")+"Camp "+(int)camp.X+", "+(int)camp.Z);LocationButton(rows,"Sleeping bag",copy.X,copy.Z,ShowCamps);Button(rows,"BIND RESPAWN",()=>{if(!CoopRequest("bind",copy.Id))game.Change(()=>game.Life.Respawn=copy.Id);ShowCamps();});Button(rows,"TRAVEL",()=>{if(CoopActive){game.Notice="Fast travel is disabled during co-op; explore together.";ShowCamps();return;}game.Save.X=player.Position.X;game.Save.Z=player.Position.Z;if(game.Travel(copy,CampSafe)=="Travelled"){Teleport(game.Save.X,game.Save.Z);ClearEnemies();}ShowCamps();});}Text(b,game.Notice);Button(b,"REST AT CURRENT BAG",()=>{if(CoopRequest("rest"))return;var camp=game.Life.Camps.Find(c=>c.Seed==game.Save.Seed&&ExpeditionGame.Distance(c.X,c.Z,player.Position.X,player.Position.Z)<4);if(camp!=null&&CampSafe(camp)&&!game.Life.Wounds.Exists(w=>!w.Patched)){game.Change(()=>game.Rested());game.Notice="Rested";}else game.Notice="Stand at a safe bag and patch bleeding first";ShowCamps();});Button(b,"BACK",CloseMenu);}
 void ShowPause(){ShowCleanPause();}
 void ImportDialog(){if(CoopActive){game.Notice="Leave co-op before importing a character.";ShowPause();return;}var fd=new FileDialog{FileMode=FileDialog.FileModeEnum.OpenFile,Access=FileDialog.AccessEnum.Filesystem,Title="Select legacy profiles/expedition-loot.json"};fd.Filters=new[]{"*.json ; Expedition character profile"};ui.AddChild(fd);fd.FileSelected+=path=>{try{string worlds=Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(path)),"worlds");if(game.ImportLegacy(path,worlds)){AssignLegacyBuilders();ExitDungeon(false);ClearEnemies();ClearChildren(worldRoot);props.Clear();uniqueObjects.Clear();RebuildTerrain();SyncStructures();Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);}ShowPause();}catch(Exception ex){game.Notice="Import failed / "+ex.Message;ShowPause();}fd.QueueFree();};fd.Canceled+=()=>fd.QueueFree();fd.PopupCentered(new Vector2I(900,600));}
 void ShowMap(){var b=Panel("WORLD ATLAS / 9 KM / SEED "+game.Save.Seed);var map=new ExpeditionMapCanvas{World=game.World,Journey=game.Life.Journey,PlayerPosition=player.Position,PinName=HasLocationPin?locationPinName:"",PinX=locationPinX,PinZ=locationPinZ,CustomMinimumSize=new Vector2(880,520)};b.AddChild(map);if(HasLocationPin){Text(b,"PIN / "+locationPinName+" / "+ExpeditionGame.Distance(player.Position.X,player.Position.Z,locationPinX,locationPinZ).ToString("0")+"m away");Button(b,"CLEAR LOCATION PIN",()=>{locationPinName="";ShowMap();});if(locationPinBack!=null)Button(b,"BACK TO LOCATION DETAILS",locationPinBack);}var routes=new HBoxContainer();b.AddChild(routes);LocationButton(b,"YOUR HOME / SETTLEMENT",ExpeditionWorld.HomeX,ExpeditionWorld.HomeZ,()=>ShowCommunity());Button(routes,"BOSS LOCATIONS",ShowCampaignGuide);Button(routes,"WORLD CHANGES",ShowWorldWorksLedger);Button(routes,"EXPEDITION PLANNER / F5",ShowJourneyPlanner);Button(b,"TOGGLE SPAWN HEATMAP",()=>{map.Heat=!map.Heat;map.QueueRedraw();});Button(b,"HEATMAP: SWITCH DAY / NIGHT",()=>{map.NightHeat=!map.NightHeat;map.Heat=true;map.QueueRedraw();});Text(b,"City and suburbs lie northwest; industry and rail yards occupy the centre. The highway connects rural farmland, eastern lakes and southern woodland. Follow local roads and bridges. Heatmap shows day/night danger.");Button(b,"BACK",CloseMenu);}
 void ShowRelay(){var b=Panel("EXISTING TLS RELAY / CONNECTION PROBE");Text(b,"Transport retained on TCP 28747. This tests connectivity only; Expedition world synchronization is not implemented.");var address=new LineEdit{PlaceholderText="Relay address"};var pin=new LineEdit{PlaceholderText="Certificate SHA256 fingerprint"};b.AddChild(address);b.AddChild(pin);Button(b,"CONNECT",()=>{relay?.Dispose();relay=new RelayLink();relay.Connect(new RelayConfig{Address=address.Text.Trim(),CertificateSha256=pin.Text.Trim(),Port=28747});CloseMenu();});Button(b,"BACK",CloseMenu);}
 void ShowLetter(int kind=1){var b=Panel(JournalText.SceneNames[kind]);Text(b,JournalText.SceneNotes[kind]);Button(b,"BACK",CloseMenu);}
 void ShowJournal(){var frame=Panel("FRAGMENTS / JOURNAL");Button(frame,"FIELD GUIDE / EXPLORATION RECORD",ShowFieldGuide);Button(frame,"THE WORLD YOU LEAVE / WORLD CHANGES",ShowWorldWorksLedger);var scroll=new ScrollContainer{CustomMinimumSize=new(900,470)};frame.AddChild(scroll);var b=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(b);Button(b,"THE SOUTH BANK / YOUR JOURNEY",ShowCampaignGuide);EncounterJournal(b);if(game.Profile.Journal.Seen.Exists(id=>id.StartsWith("crash/")))Button(b,"SO I WON'T GO ALONE",ShowCrashJournal);if(game.Profile.Journal.Seen.Contains("checkpoint/room"))Button(b,"THE PRICE OF CROSSING / THE LOCKED ROOM",()=>{var page=Panel("THE PRICE OF CROSSING");Text(page,"Three starving survivors charged a food toll on a bridge. Their own bowls were empty. The provisions went through a feeding slot to children in a locked room.\n\nA traveller begged to keep his pack. The guards told him to put it down.");Button(page,"BACK",CloseMenu);});if(game.Profile.Journal.Seen.Contains("birthday/sammy"))Button(b,"SAMMY'S NINTH BIRTHDAY",ShowBirthdayNote);for(int page=0;page<4;page++){int copy=page;if(game.Profile.Journal.Seen.Contains("last-letter/"+page))Button(b,LastLetterTitles[page],()=>ShowLastLetter(copy));}if(game.Profile.Journal.Seen.Contains(FeverJournal))Button(b,"JUST A FEVER / REMEMBERED",()=>ShowFeverNotebook(true));if(game.Profile.Journal.Seen.Contains(WoodlandJournal))Button(b,"THE FIRST FISH / WOODLAND CAMP",ShowWoodlandJournal);Text(b,game.Profile.Journal.Seen.Count+" recovered fragments. Search abandoned locations with E.");var kinds=new System.Collections.Generic.HashSet<int>();foreach(string id in game.Profile.Journal.Seen){if(id.StartsWith("crash/")||id.StartsWith("checkpoint/")||id.StartsWith("birthday/")||id.StartsWith("last-letter/")||id.StartsWith("fever/")||id.StartsWith("family/")||id.StartsWith("mill-note/"))continue;int kind;string tail=id.Substring(id.LastIndexOf('/')+1);if(int.TryParse(tail,out kind)&&kind>=0&&kind<6)kinds.Add(kind);else if(id.EndsWith("/letter"))kinds.Add(1);}foreach(int kind in kinds){int copy=kind;Button(b,JournalText.SceneNames[kind],()=>ShowLetter(copy));}for(int i=0;i<FamilyTitles.Length;i++){int copy=i;if(game.Profile.Journal.Seen.Contains("family/note/"+i))Button(b,FamilyTitles[i],()=>ShowFamilyNote(copy));}for(int i=0;i<MillNotes.Length;i++){int copy=i;if(game.Profile.Journal.Seen.Contains("mill-note/"+i))Button(b,MillNoteTitles[i],()=>ShowMillNote(copy));}Button(frame,"BACK",CloseMenu);}
}
internal partial class ExpeditionMapCanvas:Control {
 void DrawLetterMarkers(){double cx=ExpeditionLastLetter.ChurchX(World);DrawCircle(Map(cx,ExpeditionLastLetter.ChurchZ),5,Colors.LightBlue);DrawString(ThemeDB.FallbackFont,Map(cx,ExpeditionLastLetter.ChurchZ)+new Vector2(8,0),"ST. BRIGID'S",HorizontalAlignment.Left,-1,11,Colors.LightBlue);if(World.Changes?.LastLetter?.Stage==1){var p=Map(ExpeditionLastLetter.HomeX(World),ExpeditionLastLetter.HomeZ);DrawCircle(p,6,Colors.Gold);DrawString(ThemeDB.FallbackFont,p+new Vector2(-135,14),"LETTER / SAMUEL",HorizontalAlignment.Left,-1,11,Colors.Gold);}}

 internal ExpeditionWorld World;internal Vector3 PlayerPosition;internal bool Heat,NightHeat;
 Rect2 AtlasMapRect{get{float side=Math.Min(Size.X,Size.Y);return new Rect2(new Vector2((Size.X-side)/2,(Size.Y-side)/2),new Vector2(side,side));}}
 Vector2 Map(double x,double z){var rect=AtlasMapRect;return rect.Position+new Vector2((float)((x-ExpeditionWorld.MinX)/9000*rect.Size.X),(float)((z-ExpeditionWorld.MinZ)/9000*rect.Size.Y));}

 public override void _Draw(){if(World==null)return;DrawAtlasMap();DrawLivingMap();DrawWorkMap();DrawLetterMarkers();DrawCircle(Map(World.SafeStoryX(World.RouteX(-930)+55,-930,32),-930),5,Colors.LightBlue);DrawString(ThemeDB.FallbackFont,Map(World.SafeStoryX(World.RouteX(-930)+55,-930,32),-930)+new Vector2(8,0),"WILLOW HOUSE",HorizontalAlignment.Left,-1,11,Colors.LightBlue);DrawCircle(Map(World.SafeStoryX(World.RouteX(-780)+90,-780,38),-780),6,new Color(.85f,.35f,.12f));DrawString(ThemeDB.FallbackFont,Map(World.SafeStoryX(World.RouteX(-780)+90,-780,38),-780)+new Vector2(9,0),"LUMBER MILL",HorizontalAlignment.Left,-1,11,Colors.Orange);if(World.Changes?.Community is ExpeditionCommunity camp){foreach(var n in camp.Survivors)if(!n.Member){DrawCircle(Map(n.X,n.Z),5,Colors.Cyan);DrawString(ThemeDB.FallbackFont,Map(n.X,n.Z)+new Vector2(8,0),"RESCUE / "+n.Name,HorizontalAlignment.Left,-1,10,Colors.Cyan);}if(camp.Established){DrawCircle(Map(camp.X,camp.Z),6,Colors.LightGreen);DrawString(ThemeDB.FallbackFont,Map(camp.X,camp.Z)+new Vector2(8,0),"YOUR COMMUNITY",HorizontalAlignment.Left,-1,11,Colors.LightGreen);}}foreach(var d in ExpeditionDungeon.Nearby(World,0,0))DrawCircle(Map(d.X,d.Z),4,Colors.Orange);DrawCircle(Map(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ),7,Colors.LightGreen);DrawString(ThemeDB.FallbackFont,Map(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ)+new Vector2(-130,-10),"BRIAR LANE / START",HorizontalAlignment.Left,-1,13,Colors.White);DrawString(ThemeDB.FallbackFont,new Vector2(12,20),Heat?(NightHeat?"SPAWN PRESSURE / NIGHT":"SPAWN PRESSURE / DAY"):"NORTH / 9 KM WORLD ATLAS",HorizontalAlignment.Left,-1,13,Colors.White);DrawCircle(Map(PlayerPosition.X,PlayerPosition.Z),5,Colors.White);DrawJourneyMap();var home=Map(ExpeditionWorld.HomeX,ExpeditionWorld.HomeZ);DrawCircle(home,7,Colors.LightGreen);DrawString(ThemeDB.FallbackFont,home+new Vector2(-115,20),"YOUR HOUSE / SETTLEMENT",HorizontalAlignment.Left,-1,11,Colors.LightGreen);DrawMapStructure();DrawLocationPin();}
